command:
if (!game.user.isGM) return ui.notifications.warn('Dispel Effect from Unit(s) is GM-only.');

const units = (canvas.tokens?.controlled ?? []).filter(token => token.actor?.type === 'Character');
if (!units.length) return ui.notifications.warn('Select one or more units first.');

const present = new Set();
for (const token of units) {
  for (const effect of token.actor.effects) present.add(effect.name);
}

const options = [...present].sort((a, b) => a.localeCompare(b))
  .map(name => `<option value="${foundry.utils.escapeHTML(name)}"></option>`).join('');

const raw = await foundry.applications.api.DialogV2.wait({
  window: { title: 'Dispel Effect from Unit(s)' },
  classes: ['emblem-rpg', 'dialog-editor'],
  position: { width: 440 },
  content: `
    <div class="ed-container">
      <div class="ed-section">
        <label class="ed-label" for="emblem-dispel-names">Effect names, separated by commas</label>
        <input id="emblem-dispel-names" class="ed-input" type="text" name="names" list="emblem-dispel-present" placeholder="Poisoned, Restrained" autofocus />
        <datalist id="emblem-dispel-present">${options}</datalist>
      </div>
      ${present.size ? '' : '<div class="ed-section"><p class="ed-description">The selected unit(s) carry no active effects.</p></div>'}
    </div>`,
  buttons: [
    {
      action: 'dispel',
      label: 'Dispel',
      icon: 'fas fa-wind',
      default: true,
      callback: (event, button) => button.form.elements.names.value
    },
    { action: 'cancel', label: 'Cancel', callback: () => null }
  ],
  rejectClose: false
});

if (typeof raw !== 'string') return;

const wanted = raw.split(',').map(entry => entry.trim().toLowerCase()).filter(Boolean);
if (!wanted.length) return ui.notifications.warn('No effect names entered.');

const matched = new Set();
const removedByUnit = [];
const failures = [];

for (const token of units) {
  const actor = token.actor;
  const ids = [];
  const names = [];
  for (const effect of actor.effects) {
    const keys = [effect.name, ...(effect.statuses ?? [])]
      .filter(Boolean).map(key => String(key).trim().toLowerCase());
    const hit = wanted.find(entry => keys.includes(entry));
    if (!hit) continue;
    matched.add(hit);
    ids.push(effect.id);
    names.push(effect.name);
  }
  if (!ids.length) continue;
  try {
    await actor.deleteEmbeddedDocuments('ActiveEffect', ids);
    removedByUnit.push({ unit: actor.name, removed: names.join(', '), count: ids.length });
  } catch (err) {
    failures.push({ unit: actor.name, error: err.message });
    console.error(`emblem-rpg | Dispel failed for ${actor.name}:`, err);
  }
}

const missed = wanted.filter(entry => !matched.has(entry));
const total = removedByUnit.reduce((sum, row) => sum + row.count, 0);

console.group(`emblem-rpg | Dispel Effect from Unit(s) — ${total} effect(s) removed`);
if (removedByUnit.length) console.table(removedByUnit);
if (missed.length) console.log('Not found on any selected unit:', missed);
if (failures.length) console.table(failures);
console.groupEnd();

if (failures.length) ui.notifications.error(`Removed ${total} effect(s); ${failures.length} unit(s) failed, see console.`);
else if (!total) ui.notifications.warn(`No matching effects found for: ${wanted.join(', ')}.`);
else if (missed.length) ui.notifications.info(`Removed ${total} effect(s). Not found: ${missed.join(', ')}.`);
else ui.notifications.info(`Removed ${total} effect(s).`);
